def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(r"\s*(<=|>=|<>|[A-Z]+[1-9][0-9]?|[A-Z]+|[0-9]+|[()+\-*/,:=<>])")
    parsed = {}

    def parse(content):
        if not content.startswith("="):
            return ("num", int(content))

        tokens = []
        pos = 1
        while pos < len(content):
            match = token_re.match(content, pos)
            if match is None:
                if content[pos:].strip() == "":
                    break
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()

        # Iterative shunting-yard parser. Function calls and parentheses use
        # frames; comparison operators are permitted only in IF conditions.
        values = []
        operators = []
        frames = []

        precedence = {
            "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
            "+": 1, "-": 1, "*": 2, "/": 2, "u-": 3,
        }

        def reduce_one():
            op = operators.pop()
            if op == "u-":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("op", op, left, right))

        def finish_argument(frame):
            while operators and operators[-1] != "(":
                reduce_one()
            if len(values) != frame["base"] + 1:
                raise ValueError("Invalid argument")
            frame["args"].append(values.pop())

        i = 0
        expecting_operand = True
        while i < len(tokens):
            token = tokens[i]

            if expecting_operand:
                if token == "-":
                    operators.append("u-")
                    i += 1
                elif token == "(":
                    operators.append("(")
                    frames.append({"kind": "group", "base": len(values)})
                    i += 1
                elif token in ("SUM", "MIN", "MAX", "IF"):
                    operators.append("(")
                    frames.append({
                        "kind": token,
                        "base": len(values),
                        "args": [],
                    })
                    i += 2  # Skip the function name and opening parenthesis.
                elif token[0].isdigit():
                    values.append(("num", int(token)))
                    expecting_operand = False
                    i += 1
                else:
                    if i + 2 < len(tokens) and tokens[i + 1] == ":":
                        values.append(("range", token, tokens[i + 2]))
                        i += 3
                    else:
                        values.append(("ref", token))
                        i += 1
                    expecting_operand = False
            elif token in precedence:
                while (operators and operators[-1] != "("
                       and precedence[operators[-1]] >= precedence[token]):
                    reduce_one()
                operators.append(token)
                expecting_operand = True
                i += 1
            elif token == ",":
                frame = frames[-1]
                finish_argument(frame)
                expecting_operand = True
                i += 1
            elif token == ")":
                frame = frames.pop()
                while operators[-1] != "(":
                    reduce_one()
                operators.pop()
                if frame["kind"] != "group":
                    frame["args"].append(values.pop())
                    values.append(("call", frame["kind"], frame["args"]))
                expecting_operand = False
                i += 1
            else:
                raise ValueError("Invalid formula")

        while operators:
            reduce_one()
        return values[0]

    results = {}
    active = set()

    # Tasks and the value stack replace Python recursion for both formula
    # evaluation and arbitrarily long chains of cell references.
    def evaluate(start):
        tasks = [("cell", start)]
        vals = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name not in cells:
                    vals.append(0)
                elif name in results:
                    vals.append(results[name])
                elif name in active:
                    vals.append("#CYCLE!")
                else:
                    active.add(name)
                    if name not in parsed:
                        parsed[name] = parse(cells[name])
                    tasks.append(("finish_cell", name))
                    tasks.append(("eval", parsed[name]))

            elif kind == "finish_cell":
                name = task[1]
                results[name] = vals[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_type = node[0]
                if node_type == "num":
                    vals.append(node[1])
                elif node_type == "ref":
                    tasks.append(("cell", node[1]))
                elif node_type == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_type == "op":
                    tasks.append(("op_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_type == "call":
                    name, args = node[1], node[2]
                    if name == "IF":
                        tasks.append(("if_condition", args[1], args[2]))
                        tasks.append(("eval", args[0]))
                    else:
                        tasks.append(("aggregate", name, args, 0, None))
                else:
                    raise ValueError("Range outside aggregate")

            elif kind == "neg":
                value = vals.pop()
                vals.append(value if isinstance(value, str) else -value)

            elif kind == "op_left":
                op, right = task[1], task[2]
                left = vals.pop()
                if isinstance(left, str):
                    vals.append(left)
                else:
                    tasks.append(("op_right", op, left))
                    tasks.append(("eval", right))

            elif kind == "op_right":
                op, left = task[1], task[2]
                right = vals.pop()
                if isinstance(right, str):
                    vals.append(right)
                elif op == "+":
                    vals.append(left + right)
                elif op == "-":
                    vals.append(left - right)
                elif op == "*":
                    vals.append(left * right)
                elif op == "/":
                    if right == 0:
                        vals.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        vals.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    vals.append(int(left == right))
                elif op == "<>":
                    vals.append(int(left != right))
                elif op == "<":
                    vals.append(int(left < right))
                elif op == "<=":
                    vals.append(int(left <= right))
                elif op == ">":
                    vals.append(int(left > right))
                else:
                    vals.append(int(left >= right))

            elif kind == "if_condition":
                condition = vals.pop()
                if isinstance(condition, str):
                    vals.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "aggregate":
                name, args, index, accumulator = task[1:]
                if index == len(args):
                    vals.append(0 if accumulator is None else accumulator)
                else:
                    arg = args[index]
                    if arg[0] == "range":
                        first, last = arg[1], arg[2]
                        c1, c2 = sorted((ord(first[0]), ord(last[0])))
                        r1, r2 = sorted((int(first[1:]), int(last[1:])))
                        names = [
                            chr(col) + str(row)
                            for row in range(r1, r2 + 1)
                            for col in range(c1, c2 + 1)
                            if chr(col) + str(row) in cells
                        ]
                        tasks.append(("range_next", name, args, index, accumulator, names, 0))
                    else:
                        tasks.append(("aggregate_value", name, args, index, accumulator))
                        tasks.append(("eval", arg))

            elif kind == "range_next":
                name, args, index, accumulator, names, offset = task[1:]
                if offset == len(names):
                    tasks.append(("aggregate", name, args, index + 1, accumulator))
                else:
                    tasks.append(("range_value", name, args, index, accumulator, names, offset))
                    tasks.append(("cell", names[offset]))

            elif kind == "range_value":
                name, args, index, accumulator, names, offset = task[1:]
                value = vals.pop()
                if isinstance(value, str):
                    vals.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif name == "SUM":
                        accumulator += value
                    elif name == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("range_next", name, args, index, accumulator, names, offset + 1))

            elif kind == "aggregate_value":
                name, args, index, accumulator = task[1:]
                value = vals.pop()
                if isinstance(value, str):
                    vals.append(value)
                else:
                    if accumulator is None:
                        accumulator = value
                    elif name == "SUM":
                        accumulator += value
                    elif name == "MIN":
                        accumulator = min(accumulator, value)
                    else:
                        accumulator = max(accumulator, value)
                    tasks.append(("aggregate", name, args, index + 1, accumulator))

        return vals.pop()

    for name in cells:
        if name not in results:
            evaluate(name)

    return {name: results[name] for name in cells}
